func (r *mutationResolver) DelegateApproval(ctx context.Context, input gqlmodel.DelegateApprovalInput) (*worker.ApprovalDelegation, error) {
	authCtx, err := r.requirePermission(
		ctx,
		permission.ResourceApprovalDelegation,
		permission.OpCreate,
	)
	if err != nil {
		return nil, err
	}

	delegateID, err := pulid.MustParse(input.DelegateID)
	if err != nil {
		return nil, errortypes.NewValidationError(
			"delegateId",
			errortypes.ErrInvalid,
			"Delegate is invalid",
		)
	}

	// Handing over somebody else's approvals is a different act from handing
	// over your own, so it needs the wider grant rather than the create one.
	delegatorID := authCtx.UserID
	if input.DelegatorID != nil && *input.DelegatorID != "" {
		parsed, pErr := pulid.MustParse(*input.DelegatorID)
		if pErr != nil {
			return nil, errortypes.NewValidationError(
				"delegatorId",
				errortypes.ErrInvalid,
				"Delegator is invalid",
			)
		}
		if parsed != authCtx.UserID {
			if _, mErr := r.requirePermission(
				ctx,
				permission.ResourceApprovalDelegation,
				permission.OpManage,
			); mErr != nil {
				return nil, mErr
			}
		}
		delegatorID = parsed
	}

	req := &orgstructureservice.DelegateRequest{
		TenantInfo:  tenantInfo(authCtx),
		DelegatorID: delegatorID,
		DelegateID:  delegateID,
		StartsAt:    int64(intValue(input.StartsAt)),
		EndsAt:      int64Ptr(input.EndsAt),
		Reason:      stringValue(input.Reason),
		UserID:      authCtx.UserID,
	}
	if input.Scope != nil {
		req.Scope = *input.Scope
	}

	return r.orgStructureService.Delegate(ctx, req)
}

func (r *mutationResolver) RevokeApprovalDelegation(ctx context.Context, id string) (*worker.ApprovalDelegation, error) {
	authCtx, err := r.requirePermission(
		ctx,
		permission.ResourceApprovalDelegation,
		permission.OpCreate,
	)
	if err != nil {
		return nil, err
	}

	delegationID, err := pulid.MustParse(id)
	if err != nil {
		return nil, errortypes.NewValidationError(
			"id",
			errortypes.ErrInvalid,
			"Delegation is invalid",
		)
	}

	ti := tenantInfo(authCtx)
	existing, err := r.orgStructureService.ListDelegations(
		ctx,
		&repositories.ListApprovalDelegationsRequest{TenantInfo: ti, DelegatorID: authCtx.UserID},
	)
	if err != nil {
		return nil, err
	}
	// Calling back your own delegation needs nothing more than having made it;
	// calling back somebody else's is an administrative act.
	mine := false
	for _, row := range existing {
		if row != nil && row.ID == delegationID {
			mine = true
			break
		}
	}
	if !mine {
		if _, mErr := r.requirePermission(
			ctx,
			permission.ResourceApprovalDelegation,
			permission.OpManage,
		); mErr != nil {
			return nil, mErr
		}
	}

	return r.orgStructureService.RevokeDelegation(ctx, ti, delegationID, authCtx.UserID)
}

