func (r *queryResolver) ApprovalDelegations(ctx context.Context, delegatorID *string, delegateID *string, activeOnly *bool) ([]*worker.ApprovalDelegation, error) {
	authCtx, err := r.requirePermission(
		ctx,
		permission.ResourceApprovalDelegation,
		permission.OpRead,
	)
	if err != nil {
		return nil, err
	}

	delegator, err := optionalID(delegatorID)
	if err != nil {
		return nil, errortypes.NewValidationError(
			"delegatorId",
			errortypes.ErrInvalid,
			"Delegator is invalid",
		)
	}
	delegate, err := optionalID(delegateID)
	if err != nil {
		return nil, errortypes.NewValidationError(
			"delegateId",
			errortypes.ErrInvalid,
			"Delegate is invalid",
		)
	}
	// Unfiltered, the list is what the signed-in user has been handed. Reading
	// the whole organisation's delegations is an administrative act.
	if delegator.IsNil() && delegate.IsNil() {
		delegate = authCtx.UserID
	}
	if delegator != authCtx.UserID && delegate != authCtx.UserID {
		if _, mErr := r.requirePermission(
			ctx,
			permission.ResourceApprovalDelegation,
			permission.OpManage,
		); mErr != nil {
			return nil, mErr
		}
	}

	req := &repositories.ListApprovalDelegationsRequest{
		TenantInfo:   tenantInfo(authCtx),
		DelegatorID:  delegator,
		DelegateID:   delegate,
		IncludeUsers: true,
	}
	if boolValue(activeOnly) {
		req.ActiveAt = timeutils.NowUnix()
	}

	return r.orgStructureService.ListDelegations(ctx, req)
}

